.input-glow__grid {
  height: 800px;
  width: 800px;
  background-image:
    linear-gradient(to right, #0f0f10 1px, transparent 1px),
    linear-gradient(to bottom, #0f0f10 1px, transparent 1px);
  background-size: 1rem 1rem;
  background-position: center center;
  position: absolute;
  z-index: -1;
  filter: blur(1px);
}
.input-glow__white,
.input-glow__border,
.input-glow__dark-border-bg,
.input-glow__glow {
  max-height: 70px;
  max-width: 314px;
  height: 100%;
  width: 100%;
  position: absolute;
  overflow: hidden;
  z-index: -1;
  border-radius: 12px;
  filter: blur(3px);
}
.input-glow__input {
  background-color: #010201;
  border: none;
  width: 301px;
  height: 56px;
  border-radius: 10px;
  color: white;
  padding-inline: 59px;
  font-size: 18px;
}
.input-glow {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.input-glow__input::placeholder {
  color: #c0b9c0;
}

.input-glow__input:focus {
  outline: none;
}

.input-glow__main:focus-within > .input-glow__input-mask {
  display: none;
}

.input-glow__input-mask {
  pointer-events: none;
  width: 100px;
  height: 20px;
  position: absolute;
  background: linear-gradient(90deg, transparent, black);
  top: 18px;
  left: 70px;
}
.input-glow__pink-mask {
  pointer-events: none;
  width: 30px;
  height: 20px;
  position: absolute;
  background: #cf30aa;
  top: 10px;
  left: 5px;
  filter: blur(20px);
  opacity: 0.8;
  transition: all 2s;
}
.input-glow__main:hover > .input-glow__pink-mask {
  opacity: 0;
}

.input-glow__white {
  max-height: 63px;
  max-width: 307px;
  border-radius: 10px;
  filter: blur(2px);
}

.input-glow__white::before {
  content: "";
  z-index: -2;
  text-align: center;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(83deg);
  position: absolute;
  width: 600px;
  height: 600px;
  background-repeat: no-repeat;
  background-position: 0 0;
  filter: brightness(1.4);
  background-image: conic-gradient(
    rgba(0, 0, 0, 0) 0%,
    #a099d8,
    rgba(0, 0, 0, 0) 8%,
    rgba(0, 0, 0, 0) 50%,
    #dfa2da,
    rgba(0, 0, 0, 0) 58%
  );
  transition: all 2s;
}
.input-glow__border {
  max-height: 59px;
  max-width: 303px;
  border-radius: 11px;
  filter: blur(0.5px);
}
.input-glow__border::before {
  content: "";
  z-index: -2;
  text-align: center;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(70deg);
  position: absolute;
  width: 600px;
  height: 600px;
  filter: brightness(1.3);
  background-repeat: no-repeat;
  background-position: 0 0;
  background-image: conic-gradient(
    #1c191c,
    #402fb5 5%,
    #1c191c 14%,
    #1c191c 50%,
    #cf30aa 60%,
    #1c191c 64%
  );
  transition: all 2s;
}
.input-glow__dark-border-bg {
  max-height: 65px;
  max-width: 312px;
}
.input-glow__dark-border-bg::before {
  content: "";
  z-index: -2;
  text-align: center;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(82deg);
  position: absolute;
  width: 600px;
  height: 600px;
  background-repeat: no-repeat;
  background-position: 0 0;
  background-image: conic-gradient(
    rgba(0, 0, 0, 0),
    #18116a,
    rgba(0, 0, 0, 0) 10%,
    rgba(0, 0, 0, 0) 50%,
    #6e1b60,
    rgba(0, 0, 0, 0) 60%
  );
  transition: all 2s;
}
.input-glow:hover > .input-glow__dark-border-bg::before {
  transform: translate(-50%, -50%) rotate(-98deg);
}
.input-glow:hover > .input-glow__glow::before {
  transform: translate(-50%, -50%) rotate(-120deg);
}
.input-glow:hover > .input-glow__white::before {
  transform: translate(-50%, -50%) rotate(-97deg);
}
.input-glow:hover > .input-glow__border::before {
  transform: translate(-50%, -50%) rotate(-110deg);
}

.input-glow:focus-within > .input-glow__dark-border-bg::before {
  transform: translate(-50%, -50%) rotate(442deg);
  transition: all 4s;
}
.input-glow:focus-within > .input-glow__glow::before {
  transform: translate(-50%, -50%) rotate(420deg);
  transition: all 4s;
}
.input-glow:focus-within > .input-glow__white::before {
  transform: translate(-50%, -50%) rotate(443deg);
  transition: all 4s;
}
.input-glow:focus-within > .input-glow__border::before {
  transform: translate(-50%, -50%) rotate(430deg);
  transition: all 4s;
}

.input-glow__glow {
  overflow: hidden;
  filter: blur(30px);
  opacity: 0.4;
  max-height: 130px;
  max-width: 354px;
}
.input-glow__glow::before {
  content: "";
  z-index: -2;
  text-align: center;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(60deg);
  position: absolute;
  width: 999px;
  height: 999px;
  background-repeat: no-repeat;
  background-position: 0 0;
  background-image: conic-gradient(
    #000,
    #402fb5 5%,
    #000 38%,
    #000 50%,
    #cf30aa 60%,
    #000 87%
  );
  transition: all 2s;
}

@keyframes input-glow-rotate {
  100% {
    transform: translate(-50%, -50%) rotate(450deg);
  }
}

.input-glow__filter-icon {
  position: absolute;
  top: 8px;
  right: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  max-height: 40px;
  max-width: 38px;
  height: 100%;
  width: 100%;
  isolation: isolate;
  overflow: hidden;
  border-radius: 10px;
  background: linear-gradient(180deg, #161329, black, #1d1b4b);
  border: 1px solid transparent;
}
.input-glow__filter-border {
  height: 42px;
  width: 40px;
  position: absolute;
  overflow: hidden;
  top: 7px;
  right: 7px;
  border-radius: 10px;
}

.input-glow__filter-border::before {
  content: "";
  text-align: center;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(90deg);
  position: absolute;
  width: 600px;
  height: 600px;
  background-repeat: no-repeat;
  background-position: 0 0;
  filter: brightness(1.35);
  background-image: conic-gradient(
    rgba(0, 0, 0, 0),
    #3d3a4f,
    rgba(0, 0, 0, 0) 50%,
    rgba(0, 0, 0, 0) 50%,
    #3d3a4f,
    rgba(0, 0, 0, 0) 100%
  );
  animation: input-glow-rotate 4s linear infinite;
}
.input-glow__main {
  position: relative;
}
.input-glow__search-icon {
  position: absolute;
  left: 20px;
  top: 15px;
}
